options.css:
.sky-card { position: relative; width: 100%; height: calc(100% - 22px); min-height: 0; margin-top: 22px; overflow: hidden; border-radius: 8px; color: white; font-family: Inter, "Helvetica Neue", Arial, sans-serif; }
.sky-scene { width: 100%; height: 100%; display: block; }
.rain-layer { transform-box: fill-box; transform-origin: center; transition: transform .35s ease; }
.rain-field { opacity: 0; stroke: rgba(220,240,255,.82); stroke-width: 3; stroke-linecap: round; transition: opacity .35s ease; }
.rain-light { animation: rain-fall 1.15s linear infinite; }
.rain-medium { animation: rain-fall .82s linear infinite; }
.rain-heavy { animation: rain-fall .56s linear infinite; stroke-width: 4; }
.sky-card[data-rain="light"] .rain-light { opacity: .52; }
.sky-card[data-rain="moderate"] .rain-light { opacity: .58; }
.sky-card[data-rain="moderate"] .rain-medium { opacity: .68; }
.sky-card[data-rain="heavy"] .rain-light { opacity: .60; }
.sky-card[data-rain="heavy"] .rain-medium { opacity: .75; }
.sky-card[data-rain="heavy"] .rain-heavy { opacity: .88; }
.sky-bg { transition: opacity .8s ease, fill .8s ease; }
.night-bg, .stars, .moon { opacity: 0; }
.stars { fill: #fff; }
.sun { transition: opacity .6s ease, transform .8s ease; transform-origin: 230px 88px; }
.sun-core, .sun-glow { fill: #ffd45c; }
.sun-glow { opacity: .42; }
.rays { stroke: #ffe9a8; stroke-width: 5; stroke-linecap: round; }
.moon { fill: #f4f1d5; transition: opacity .8s ease; }
.moon-cut { fill: #0b1d39; }
.cloud { fill: #f7fbff; opacity: 0; transition: opacity .7s ease, fill .7s ease; }
.cloud-a { animation: drift-a var(--cloud-a-duration, 18s) ease-in-out infinite alternate; }
.cloud-b { animation: drift-b var(--cloud-b-duration, 22s) ease-in-out infinite alternate; }
.cloud-c { animation: drift-c var(--cloud-c-duration, 26s) ease-in-out infinite alternate; }
.horizon { fill: rgba(25, 70, 63, .32); }
.sky-copy { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -48%); text-align: center; text-shadow: 0 2px 9px rgba(0,0,0,.45); pointer-events: none; }
.sky-label { font-size: clamp(26px, 3vw, 46px); font-weight: 650; letter-spacing: .01em; }
.rain-label { display: none; margin-top: 2px; font-size: 15px; font-weight: 600; opacity: .95; }
.sky-card:not([data-rain="dry"]) .rain-label { display: block; }
.sky-subtitle { margin-top: 4px; font-size: 13px; opacity: .82; }
.sky-card[data-state="clear"] .sun { opacity: 1; }
.sky-card[data-state="variable-clouds"] .cloud-a, .sky-card[data-state="variable-clouds"] .cloud-b { opacity: .94; }
.sky-card[data-state="variable-clouds"] .sun { opacity: .92; }
.sky-card[data-state="cloud-obscured"] .cloud-a, .sky-card[data-state="cloud-obscured"] .cloud-b, .sky-card[data-state="cloud-obscured"] .cloud-c { opacity: .98; }
.sky-card[data-state="cloud-obscured"] .sun { opacity: .38; }
.sky-card[data-state="heavy-cloud"] .day-bg { fill: #718093; }
.sky-card[data-state="heavy-cloud"] .cloud-a, .sky-card[data-state="heavy-cloud"] .cloud-b, .sky-card[data-state="heavy-cloud"] .cloud-c { opacity: 1; fill: #cbd3dc; }
.sky-card[data-state="heavy-cloud"] .sun { opacity: .08; }
.sky-card[data-state="night-low-sun"] .day-bg { opacity: 0; }
.sky-card[data-state="night-low-sun"] .night-bg, .sky-card[data-state="night-low-sun"] .stars, .sky-card[data-state="night-low-sun"] .moon { opacity: 1; }
.sky-card[data-state="night-low-sun"] .sun, .sky-card[data-state="night-low-sun"] .cloud { opacity: 0; }
.sky-card[data-state="unavailable"] .day-bg { fill: #515966; }
.sky-card[data-state="unavailable"] .sun, .sky-card[data-state="unavailable"] .cloud { opacity: .12; }
@keyframes rain-fall { from { transform: translateY(-36px); } to { transform: translateY(36px); } }
@keyframes drift-a { from { transform: translate(430px,106px); } to { transform: translate(485px,106px); } }
@keyframes drift-b { from { transform: translate(750px,120px) scale(.8); } to { transform: translate(805px,120px) scale(.8); } }
@keyframes drift-c { from { transform: translate(990px,92px) scale(.65); } to { transform: translate(1035px,92px) scale(.65); } }

options.onRender:
const card = htmlNode.getElementById('sky-card');
const label = htmlNode.getElementById('sky-label');
const rainLabel = htmlNode.getElementById('rain-label');
if (!card || !label || !rainLabel) return;

const field = data.series?.flatMap(series => series.fields || []).find(candidate => candidate.name === 'Sky condition');
let condition = 'Unavailable';
if (field?.values?.length) {
  const index = field.values.length - 1;
  condition = field.values.get ? field.values.get(index) : field.values[index];
}
condition = condition || 'Unavailable';

const states = {
  'Clear': 'clear',
  'Variable clouds': 'variable-clouds',
  'Cloud-obscured': 'cloud-obscured',
  'Heavy cloud': 'heavy-cloud',
  'Night / low sun': 'night-low-sun',
  'Unavailable': 'unavailable'
};
card.dataset.state = states[condition] || 'unavailable';
label.textContent = condition;

const rainField = data.series?.flatMap(series => series.fields || []).find(candidate => candidate.name === 'Rain rate');
let rainRate = 0;
if (rainField?.values?.length) {
  const rainIndex = rainField.values.length - 1;
  rainRate = Number(rainField.values.get ? rainField.values.get(rainIndex) : rainField.values[rainIndex]) || 0;
}

let rainState = 'dry';
let rainText = '';
if (rainRate > 0 && rainRate < 0.10) {
  rainState = 'light';
  rainText = 'Light rain';
} else if (rainRate >= 0.10 && rainRate < 0.40) {
  rainState = 'moderate';
  rainText = 'Moderate rain';
} else if (rainRate >= 0.40) {
  rainState = 'heavy';
  rainText = 'Heavy rain';
}

card.dataset.rain = rainState;
rainLabel.textContent = rainText ? `${rainText} · ${rainRate.toFixed(2)} in/hr` : '';


const windSpeedField = data.series?.flatMap(series => series.fields || []).find(candidate => candidate.name === 'Wind speed');
const windDirectionField = data.series?.flatMap(series => series.fields || []).find(candidate => candidate.name === 'Wind direction');
let windSpeed = 0;
let windDirection = 0;
if (windSpeedField?.values?.length) {
  const i = windSpeedField.values.length - 1;
  windSpeed = Number(windSpeedField.values.get ? windSpeedField.values.get(i) : windSpeedField.values[i]) || 0;
}
if (windDirectionField?.values?.length) {
  const i = windDirectionField.values.length - 1;
  windDirection = Number(windDirectionField.values.get ? windDirectionField.values.get(i) : windDirectionField.values[i]) || 0;
}

const windFactor = Math.max(0, Math.min(1, windSpeed / 20));
const cloudFactor = Math.max(0.35, 1 - 0.65 * windFactor);
card.style.setProperty('--cloud-a-duration', `${(18 * cloudFactor).toFixed(2)}s`);
card.style.setProperty('--cloud-b-duration', `${(22 * cloudFactor).toFixed(2)}s`);
card.style.setProperty('--cloud-c-duration', `${(26 * cloudFactor).toFixed(2)}s`);

// Meteorological direction is where the wind comes FROM. Convert it to the
// horizontal component of where the air is moving TO for the scene.
const towardRadians = ((windDirection + 180) % 360) * Math.PI / 180;
const horizontalComponent = Math.sin(towardRadians);
const cloudDirection = horizontalComponent < 0 ? 'alternate-reverse' : 'alternate';
for (const cloud of htmlNode.querySelectorAll('.cloud-a, .cloud-b, .cloud-c')) {
  cloud.style.animationDirection = cloudDirection;
}

const rainLayer = htmlNode.getElementById('rain-layer');
if (rainLayer) {
  const rainTiltDegrees = Math.max(-24, Math.min(24, horizontalComponent * windFactor * 24));
  rainLayer.setAttribute('transform', `skewX(${rainTiltDegrees.toFixed(1)})`);
}
